import subprocess
import os

def run_cmd(cmd, raw_mode=False):
    # remove # lines
    lines = []
    for l in cmd.split('\n'):
        if not l.startswith('#'):
            lines.append(l)
    if raw_mode:
        run_cmd = '\n'.join(lines)
    else:
        run_cmd = ' '.join(lines)

    try:
        p = subprocess.run(["bash", "-c", run_cmd], capture_output=True, text=True, timeout=2)
        return p.stdout, p.stderr
    except subprocess.TimeoutExpired as e:
        return e.stdout.decode('utf-8', 'ignore') if e.stdout else "", "Command timed out\n"

